/* ---------- File explorer ---------- */
/* the project's files as a tree, with the ones the agent changed lettered M, A or D in their status colour and a dot on
   every folder that holds one. Its content is 16px from every edge, on shared columns (owner, 18 Nov): the top level's
   chevrons sit centred under the filter's search glyph, each level steps in 14px, and the Only changed button's glyph is
   centred over the letters' column; a row's hover and selection fill is the content's width, no wider. The card grows and
   shrinks with the folders it has open, smoothly (grow()), up to about eleven rows, then the tree scrolls with a thin
   scrollbar and its last row fades while there is more below. A filter that matches nothing shows the empty state */
.fxp{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-2)}
/* the filter sits over a hairline and the path under one, in Soft and Blueprint (owner, 21 Nov: "soft and blueprint need
   divider lines"), each 8px from it, as the rows are spaced; Clean sets the path on its foot strip */
.fxp-h{display:flex;gap:var(--dm-s-1);align-items:center;padding-bottom:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.fxp-s{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2);height:32px;padding:0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.fxp-s{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.fxp-s input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.fxp-s:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.fxp-s input::placeholder{color:var(--dm-muted)}
/* Only changed: its box ends on the content's right edge, which puts its glyph over the letters' column */
.fxp-ch{flex:none;width:28px;height:28px}
.fxp-ch[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.fxp .fxp-tree{max-height:330px;overflow:auto;overscroll-behavior:contain}
.fxp-tree.more{-webkit-mask-image:linear-gradient(180deg,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(180deg,#000 calc(100% - 28px),transparent)}
/* a thin scrollbar in the style's hairline grey, not the browser's thick one */
.fxp-tree{scrollbar-width:thin;scrollbar-color:var(--dm-rail) transparent}
.fxp-tree::-webkit-scrollbar{width:8px;height:8px}
.fxp-tree::-webkit-scrollbar-track{background:transparent}
.fxp-tree::-webkit-scrollbar-thumb{background:var(--dm-rail);border:2px solid transparent;background-clip:padding-box;border-radius:var(--dm-r-pill)}
:root:not([data-style="soft"],[data-style="clean"]) .fxp-tree:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::-webkit-scrollbar-thumb{border-radius:0}
.fxp-n{display:flex;align-items:center;gap:6px;width:100%;height:30px;padding-right:var(--dm-s-2);border-radius:var(--dm-r-sm);font-size:13px;text-align:left;color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.fxp-n:hover{background:var(--dm-row);color:var(--dm-fg)}}
/* rows fill the scrolling tree, which would cut an outside ring: theirs is drawn inside */
.fxp-n:focus-visible{outline-offset:-2px}
/* the open file: the accent tint (Blueprint's lime takes its darker mark so the tint shows on white) */
.fxp-n.sel{background:var(--dm-accent-bg);color:var(--dm-fg)}
:root:not([data-style="soft"],[data-style="clean"]) .fxp-n.sel:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:var(--dm-bp-pick)}
.fxp-n .cv{width:14px;flex:none;display:grid;place-items:center;color:var(--dm-muted);transition:transform var(--dm-t) var(--dm-ease)}
.fxp-n.open .cv{transform:rotate(90deg)}
.fxp-n .ic{color:var(--dm-muted);display:grid;flex:none}
.fxp-n .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* the agent's change, as a letter in its status colour (4.5:1 on the row, its hover and its selection) */
/* the letters and the folders' dots end on one right edge, 8px inside the row's fill (owner, 21 Nov) */
.fxp-n .bd{flex:none;width:14px;font-size:11px;font-weight:500;line-height:1;text-align:right}
.fxp-n .bd.M{color:var(--dm-warn)}.fxp-n .bd.A{color:var(--dm-ok)}.fxp-n .bd.D{color:var(--dm-bad)}
.fxp-n.D .nm{text-decoration:line-through;color:var(--dm-muted)}
/* a folder that holds a change: a dot, in the letters' column */
.fxp-n .ag{flex:none;width:14px;display:grid;place-items:center end}
.fxp-n .ag::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent))}
.fxp-k{display:grid;grid-template-rows:1fr;transition:grid-template-rows var(--dm-t) var(--dm-ease)}
.fxp-k.shut{grid-template-rows:0fr}
.fxp-k>div{overflow:hidden;min-height:0}
.fxp-f{padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fxp-st{display:block;overflow:hidden;text-overflow:ellipsis}
/* no file matches the filter: the empty state (the lab's, lab/clean): a small sketch of a file list on a white card, a
   title, one muted line and Clear filter as an outline button */
.fxp-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px 16px 12px;text-align:center}
.fxp-em[hidden]{display:none}
.fxp-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.fxp-em>span:not(.fxp-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted);overflow-wrap:anywhere}
.fxp-em .pill{margin-top:12px}
.fxp-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.fxp-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
.fxp-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
:root:not([data-style="soft"],[data-style="clean"]) .fxp-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) :is(.fxp-em-art::before,.fxp-em-art::after):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.fxp :is(.ib,.pill):active,:root[data-style="clean"] .fxp .ib:active,:root [data-style="clean"] .fxp .ib:active,:root [data-style="clean"].fxp .ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): its content 16px in from each edge; rows and the field with 10px corners; the path under
   the tree on an off-white foot strip with a hairline over it, 16px under the last row */
:root[data-style="clean"] .fxp.panel,:root [data-style="clean"] .fxp.panel,:root [data-style="clean"].fxp.panel{padding:var(--dm-s-4) var(--dm-s-4) 0}
:root[data-style="clean"] .fxp-h,:root [data-style="clean"] .fxp-h,:root [data-style="clean"].fxp-h{padding-bottom:0;border-bottom:0}
:root[data-style="clean"] .fxp-n,:root [data-style="clean"] .fxp-n,:root [data-style="clean"].fxp-n{border-radius:10px}
:root[data-style="clean"] .fxp-n.sel,:root [data-style="clean"] .fxp-n.sel,:root [data-style="clean"].fxp-n.sel{background:var(--dm-row-on)}
:root[data-style="clean"] .fxp-f,:root [data-style="clean"] .fxp-f,:root [data-style="clean"].fxp-f{margin:var(--dm-s-2) calc(-1 * var(--dm-s-4)) 0;padding:calc(var(--dm-strip-y) + 5px) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .fxp-ch,:root [data-style="clean"] .fxp-ch,:root [data-style="clean"].fxp-ch{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .fxp-ch[aria-pressed="true"],:root [data-style="clean"] .fxp-ch[aria-pressed="true"],:root [data-style="clean"].fxp-ch[aria-pressed="true"]{background:var(--dm-row-on);color:var(--dm-fg);box-shadow:none}

DM.def('file-explorer', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search','xs')).replace('{filter}', I('filter','xs'));
  // Clean's one hover: a highlight that glides from row to row (hoverGlide)
  c.offs.push(hoverGlide($('.fxp-tree', r), '.fxp-n', { keep:'.sel' }));
  const T = { n:'', k:[
    { n:'src', k:[
      { n:'components', k:[ { n:'PlanCard.tsx', s:'M' }, { n:'PriceTag.tsx', s:'A' }, { n:'Button.tsx' }, { n:'LegacyCTA.tsx', s:'D' } ] },
      { n:'styles', k:[ { n:'tokens.css', s:'M' }, { n:'globals.css' } ] },
      { n:'pages', k:[ { n:'pricing.mdx', s:'M' }, { n:'index.mdx' } ] }
    ]},
    { n:'public', k:[ { n:'og-pricing.png', s:'A' }, { n:'favicon.svg' } ] },
    { n:'package.json' }, { n:'README.md' }
  ]};
  const root = $('.fxp', r) || r, tree = $('.fxp-tree', r), inp = $('.fxp-s input', r), chB = $('.fxp-ch', r), st = $('.fxp-st', r), em = $('.fxp-em', r);
  // the folders open at first: the components the agent changed, with the other folders closed on their dots
  const open = new Set(['src','src/components']); let only = false, sel = 'src/components/PlanCard.tsx';
  const changed = n => n.s || (n.k && n.k.some(changed));
  const match = (n, q) => !q || n.n.toLowerCase().includes(q) || (n.k && n.k.some(k => match(k, q)));
  const ext = n => /\.(tsx)$/.test(n) ? 'code' : /\.css$/.test(n) ? 'palette' : /\.png|\.svg$/.test(n) ? 'image' : 'file-text';
  // each level steps in 14px from the top level's 9px, which puts its chevrons under the filter's search glyph
  function build(n, path, d, q){
    return n.k.filter(k => match(k, q) && (!only || changed(k))).map(k => {
      const p = path ? path + '/' + k.n : k.n, isD = !!k.k, op = isD && (open.has(p) || !!q || only);
      return `<button class="fxp-n${isD && op ? ' open' : ''}${p === sel ? ' sel' : ''}${k.s ? ' ' + k.s : ''}" data-p="${p}" ${isD ? `data-d="1" aria-expanded="${op}"` : `aria-selected="${p === sel}"`} style="padding-left:${9 + d * 14}px" role="treeitem"><span class="cv">${isD ? I('chev-r','xs') : ''}</span><span class="ic">${I(isD ? 'folder' : ext(k.n),'xs')}</span><span class="nm">${k.n}</span>${k.s ? `<span class="bd ${k.s}" aria-label="${{ M:'Modified', A:'Added', D:'Deleted' }[k.s]}">${k.s}</span>` : isD && changed(k) ? '<span class="ag" aria-hidden="true"></span>' : ''}</button>` + (isD ? `<div class="fxp-k${op ? '' : ' shut'}" role="group"${op ? '' : ' inert'}><div>${build(k, p, d + 1, q)}</div></div>` : '');
    }).join('');
  }
  // while there is more of the tree below, its last row fades at the edge instead of being cut off
  // (a row's entrance lifts it a few pixels, so less than half a row more doesn't count)
  const edge = () => tree.classList.toggle('more', tree.scrollTop + tree.clientHeight < tree.scrollHeight - 12);
  c.on(tree, 'scroll', edge, { passive:true }); c.on(tree, 'transitionend', edge); c.on(tree, 'animationend', edge);
  const ro = new ResizeObserver(edge); ro.observe(tree); c.offs.push(() => ro.disconnect());
  function paint(){
    const q = inp.value.trim().toLowerCase();
    tree.innerHTML = build(T, '', 0, q);
    // nothing matches: the empty state says so, and Clear filter brings the tree back
    em.hidden = !!tree.children.length; tree.hidden = !tree.children.length;
    if (!tree.children.length) $('span:not(.fxp-em-art)', em).textContent = `Nothing in the project is called “${inp.value.trim()}”.`;
    $$('.fxp-n', tree).forEach(b => b.onclick = () => {
      if (b.dataset.d){ const p = b.dataset.p, k = b.nextElementSibling; const o = !open.has(p); o ? open.add(p) : open.delete(p); b.classList.toggle('open', o); b.setAttribute('aria-expanded', o); k.classList.toggle('shut', !o); k.inert = !o; }
      else { sel = b.dataset.p; $$('.fxp-n:not([data-d])', tree).forEach(x => { x.classList.toggle('sel', x === b); x.setAttribute('aria-selected', x === b); }); swap(st, sel); }
    });
    requestAnimationFrame(edge);
  }
  inp.oninput = paint;
  $('.pill', em).onclick = () => { inp.value = ''; paint(); stagger($$('.fxp-n', tree), 25); inp.focus({ preventScroll:true }); };
  chB.onclick = () => { only = !only; chB.setAttribute('aria-pressed', only); swap(st, only ? '6 files changed by the agent' : sel); paint(); stagger($$('.fxp-n', tree), 25); };
  st.textContent = sel; paint(); stagger($$('.fxp-n', tree), 25);
  // the card grows as folders open and shrinks as they close or the filter narrows (owner, 17 Nov: no room kept for later)
  c.offs.push(grow(root));
});
